/* eslint-disable max-lines-per-function */

'use strict';

// MODULES //

var anchorPositions = require( '@stdlib/plot/vega/base/anchor-positions' );
var fontStyles = require( '@stdlib/plot/vega/base/font-styles' );
var fontWeights = require( '@stdlib/plot/vega/base/font-weights' );
var textAlignments = require( '@stdlib/plot/vega/base/text-alignments' );
var verticalBaselines = require( '@stdlib/plot/vega/base/vertical-baselines' );
var axisLabelOverlaps = require( '@stdlib/plot/vega/axis/label-overlaps' );
var legendDirections = require( '@stdlib/plot/vega/legend/directions' );
var legendOrientations = require( '@stdlib/plot/vega/legend/orientations' );
var legendTypes = require( '@stdlib/plot/vega/legend/types' );
var titleOrientations = require( '@stdlib/plot/vega/title/orientations' );


// MAIN //

/**
* Returns an editor configuration for legend properties.
*
* @returns {Object} configuration
*
* @example
* var o = config();
* // returns {...}
*/
function config() {
	return {
		'direction': {
			'description': 'legend direction',
			'property': 'direction',
			'default': 'vertical',
			'type': 'oneOf',
			'values': legendDirections()
		},
		'labelAlign': {
			'description': 'horizontal text alignment of legend labels',
			'property': 'labelAlign',
			'default': '',
			'type': 'oneOf',
			'values': textAlignments()
		},
		'labelBaseline': {
			'description': 'vertical text baseline of legend labels',
			'property': 'labelBaseline',
			'default': '',
			'type': 'oneOf',
			'values': verticalBaselines()
		},
		'labelColor': {
			'description': 'color of legend labels',
			'property': 'labelColor',
			'default': '#000',
			'type': 'color'
		},
		'labelFont': {
			'description': 'font of legend labels',
			'property': 'labelFont',
			'default': 'sans-serif',
			'type': 'string'
		},
		'labelFontSize': {
			'description': 'font size of legend labels',
			'property': 'labelFontSize',
			'default': 10,
			'type': 'number',
			'min': 0,
			'step': 1,
			'units': 'px'
		},
		'labelFontStyle': {
			'description': 'font style of legend labels',
			'property': 'labelFontStyle',
			'default': 'normal',
			'type': 'oneOf',
			'values': fontStyles()
		},
		'labelFontWeight': {
			'description': 'font weight of legend labels',
			'property': 'labelFontWeight',
			'default': 'normal',
			'type': 'oneOf',
			'values': fontWeights()
		},
		'labelLimit': {
			'description': 'maximum allowed length of legend labels',
			'property': 'labelLimit',
			'default': 10000,
			'type': 'number',
			'min': 0,
			'step': 1,
			'units': 'px'
		},
		'labelOffset': {
			'description': 'offset between legend labels and their corresponding symbol or gradient',
			'property': 'labelOffset',
			'default': 10,
			'type': 'number',
			'units': 'px'
		},
		'labelOpacity': {
			'description': 'opacity of legend labels',
			'property': 'labelOpacity',
			'default': 1,
			'type': 'number',
			'min': 0,
			'max': 1
		},
		'labelOverlap': {
			'description': 'strategy to use for resolving overlapping legend labels',
			'property': 'labelOverlap',
			'default': '',
			'type': 'oneOf',
			'values': axisLabelOverlaps()
		},
		'labelSeparation': {
			'description': 'minimum separation between legend label bounding boxes',
			'property': 'labelSeparation',
			'default': 0,
			'type': 'number',
			'min': 0,
			'step': 1,
			'units': 'px'
		},
		'orient': {
			'description': 'legend orientation',
			'property': 'orient',
			'default': 'right',
			'type': 'oneOf',
			'values': legendOrientations()
		},
		'title': {
			'description': 'legend title text',
			'property': 'title',
			'default': '',
			'type': 'string'
		},
		'titleAlign': {
			'description': 'horizontal text alignment of the legend title',
			'property': 'titleAlign',
			'default': '',
			'type': 'oneOf',
			'values': textAlignments()
		},
		'titleAnchor': {
			'description': 'anchor position for placing the legend title',
			'property': 'titleAnchor',
			'default': '',
			'type': 'oneOf',
			'values': anchorPositions()
		},
		'titleBaseline': {
			'description': 'vertical text baseline of the legend title',
			'property': 'titleBaseline',
			'default': '',
			'type': 'oneOf',
			'values': verticalBaselines()
		},
		'titleColor': {
			'description': 'color of the legend title',
			'property': 'titleColor',
			'default': '#000',
			'type': 'color'
		},
		'titleFont': {
			'description': 'font of the legend title',
			'property': 'titleFont',
			'default': 'sans-serif',
			'type': 'string'
		},
		'titleFontSize': {
			'description': 'font size of the legend title',
			'property': 'titleFontSize',
			'default': 11,
			'min': 0,
			'step': 1,
			'units': 'px',
			'type': 'number'
		},
		'titleFontStyle': {
			'description': 'font style of the legend title',
			'property': 'titleFontStyle',
			'default': 'normal',
			'type': 'oneOf',
			'values': fontStyles()
		},
		'titleFontWeight': {
			'description': 'font weight of the legend title',
			'property': 'titleFontWeight',
			'default': 'bold',
			'type': 'oneOf',
			'values': fontWeights()
		},
		'titleLimit': {
			'description': 'maximum allowed length of the legend title',
			'property': 'titleLimit',
			'default': 10000,
			'min': 0,
			'step': 1,
			'units': 'px',
			'type': 'number'
		},
		'titleLineHeight': {
			'description': 'line height for multi-line legend title',
			'property': 'titleLineHeight',
			'default': 1,
			'min': 0,
			'type': 'number',
			'step': 1,
			'units': 'px'
		},
		'titleOpacity': {
			'description': 'opacity of the legend title',
			'property': 'titleOpacity',
			'default': 1,
			'min': 0,
			'max': 1,
			'type': 'number'
		},
		'titleOrient': {
			'description': 'orientation of the legend title',
			'property': 'titleOrient',
			'default': 'top',
			'type': 'oneOf',
			'values': titleOrientations()
		},
		'titlePadding': {
			'description': 'padding between the legend title and entries',
			'property': 'titlePadding',
			'default': 0,
			'units': 'px',
			'type': 'number'
		},
		'type': {
			'description': 'legend type',
			'property': 'type',
			'default': '',
			'type': 'oneOf',
			'values': legendTypes()
		}
	};
}


// EXPORTS //

module.exports = config;
